   await installScript({text:"(function(){\n  'use strict';\n  const required={\n    exams:'loadExams',questions:'loadQuestions',examCreate:'createExam',\n    questionSave:'saveQuestion',fullPreview:'openFullQuestions',\n    printPDF:'printQuestionsPDF',importWord:'importWord',importPDF:'importPDF',\n    copyQuestions:'openQuestionCopyBank',saveTimer:'editExamTime'\n  };\n  const missing=Object.entries(required).filter(([,name])=>typeof window[name]!=='function');\n  if(missing.length){\n    console.warn('[Prudle quiz feature audit] Missing functions:',missing);\n    const el=document.getElementById('prudleDataStatus');\n    if(el){el.hidden=false;el.textContent='بعض وظائف الاختبارات لم تُحمّل: '+missing.map(x=>x[1]).join(', ');}\n  }\n  function getActiveExam(){\n    try { return typeof CURRENT_PREVIEW_EXAM!=='undefined' ? String(CURRENT_PREVIEW_EXAM||'').trim():''; }\n    catch(_){return '';}\n  }\n  window.prudleOpenPdfPreview=async function(mode){\n    const examId=getActiveExam();\n    if(!examId){alert('اختر اختبارًا من البطاقات أولًا لعرض الأسئلة أو PDF.');return;}\n    const modal=document.getElementById('questionsModal');\n    if(typeof window.openFullQuestions!=='function'){\n      alert('تعذر تحميل نافذة عرض الأسئلة الأصلية.');return;\n    }\n    try{\n      await window.openFullQuestions(examId);\n      const wrap=document.getElementById('modalQuestionsWrap');\n      if(!modal || !wrap || !wrap.querySelector('.modal-q-card')){\n        console.warn('[Prudle PDF] No printable questions found in selected exam',examId);\n        return;\n      }\n      // Print is intentionally initiated by an explicit click on the original\n      // modal's PDF buttons to avoid browser popup/print blocking.\n      if(mode==='answers' || mode==='questions' || mode==='review'){\n        const btn=modal.querySelector(mode==='answers' ? '.print-answers-btn' :\n          mode==='review' ? '.print-review-btn' : '.print-questions-btn:not(.print-answers-btn):not(.print-review-btn)');\n        if(btn){ btn.focus({preventScroll:true}); }\n      }\n    }catch(err){\n      console.error('[Prudle PDF] Original exam preview failed:',err);\n      alert('تعذر عرض أسئلة الاختبار: '+(err?.message||err));\n    }\n  };\n  const box=document.getElementById('examPreviewBox');\n  const section=box?.closest('.box');\n  if(section && !document.getElementById('prudleQuickPdfTools')){\n    const bar=document.createElement('div');\n    bar.id='prudleQuickPdfTools';\n    bar.setAttribute('dir','rtl');\n    bar.innerHTML=`\n      <span class=\"prudle-pdf-label\">عرض الاختبار والطباعة (اختر بطاقة اختبار أولًا)</span>\n      <button type=\"button\" data-pdf=\"review\">👁️ معاينة الأسئلة</button>\n      <button type=\"button\" data-pdf=\"questions\">📄 PDF الأسئلة</button>\n      <button type=\"button\" data-pdf=\"answers\">✅ PDF الأسئلة والإجابات</button>`;\n    const tabs=document.getElementById('courseTabs');\n    if(tabs) tabs.before(bar);else box.after(bar);\n    bar.addEventListener('click',e=>{\n      const btn=e.target.closest('button[data-pdf]');\n      if(btn)window.prudleOpenPdfPreview(btn.dataset.pdf);\n    });\n  }\n  // Preserve native controls and leave original print code responsible for A4.\n})();"});
   await installScript({text:"(function(){\n 'use strict';\n if(document.getElementById('prudleWorkspace'))return;\n const $=id=>document.getElementById(id);\n const preview=$('examPreviewBox')?.closest('.box');\n const editor=$('examSelect')?.closest('.box');\n const imports=$('wordFile')?.closest('.box');\n const ai=$('prudleAIQuiz');\n if(!preview||!editor||!imports){console.warn('Prudle workspace: original controls not found');return;}\n const css=document.createElement('style');\n css.id='prudleWorkspaceStyle';css.textContent=`\n #prudleWorkspace{--pw-blue:#174575;--pw-border:#d8e5f3;font-family:Tajawal,Arial,sans-serif;direction:rtl;max-width:1680px;margin:20px auto;padding:0 14px;color:#163654}\n #prudleWorkspace *{box-sizing:border-box}\n #prudleWorkspace .pw-heading{background:linear-gradient(110deg,#154471,#2776b5);color:white;border-radius:20px;padding:19px 24px;margin-bottom:16px;display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}\n #prudleWorkspace .pw-heading strong{font-size:24px}#prudleWorkspace .pw-heading small{display:block;color:#dbeafe;margin-top:5px;font-size:13px}\n #prudleWorkspace .pw-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:16px;align-items:start}\n #prudleWorkspace .pw-nav{position:sticky;top:12px;background:white;border:1px solid var(--pw-border);border-radius:18px;padding:14px;box-shadow:0 8px 25px #17457514;max-height:calc(100vh - 24px);overflow-y:auto}\n #prudleWorkspace .pw-nav-title{font-weight:900;color:var(--pw-blue);font-size:17px;padding:8px 10px 15px}\n #prudleWorkspace .pw-nav button{display:flex;width:100%;align-items:center;gap:10px;justify-content:flex-start;text-align:right;border:1px solid transparent;background:#f3f7fc;color:#244867;margin:0 0 8px;padding:13px 10px;border-radius:11px;font:800 14px Tajawal,Arial,sans-serif;cursor:pointer;box-shadow:none}\n #prudleWorkspace .pw-nav button.pw-active{background:#174575;color:white}#prudleWorkspace .pw-nav button:hover{border-color:#8fb5dd}\n #prudleWorkspace .pw-main{min-width:0}#prudleWorkspace .pw-panel{display:none}#prudleWorkspace .pw-panel.pw-open{display:block}\n #prudleWorkspace .pw-paper{background:white;min-height:600px;box-shadow:0 10px 35px #163b6214;border:1px solid #d5e0ed;border-radius:18px;padding:24px 26px;margin-bottom:16px}\n #prudleWorkspace .pw-paperhead{border-bottom:2px solid #dbe7f3;padding-bottom:16px;margin-bottom:22px;display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}\n #prudleWorkspace .pw-paperhead h2{margin:0;color:#174575;font-size:23px}#prudleWorkspace .pw-desc{font-size:13px;color:#60778d;line-height:1.7}\n #prudleWorkspace .pw-paper #questionsList{margin-top:18px!important;max-width:100%;min-width:0;direction:ltr}\n #prudleWorkspace .pw-paper #questionsList>*,#prudleWorkspace .pw-paper #questionsList .question-card{max-width:100%;min-width:0;overflow-wrap:anywhere}\n #prudleWorkspace .pw-paper #examPreviewBox{height:190px!important;max-height:260px!important;padding:10px!important;margin-top:10px!important}\n #prudleWorkspace .pw-panel .box{max-width:100%;margin:0 0 16px;box-shadow:none;border:1px solid #dce6f3;border-radius:16px;padding:18px;background:white}\n #prudleWorkspace .pw-panel input,#prudleWorkspace .pw-panel textarea,#prudleWorkspace .pw-panel select{max-width:100%;font-family:inherit}\n #prudleWorkspace .pw-panel #question{font-size:21px;font-weight:800;min-height:125px;line-height:1.6;background:#fff;direction:ltr;text-align:left}\n #prudleWorkspace .pw-panel #optionsBox{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n #prudleWorkspace .pw-panel #optionsBox input{width:100%;margin:0;min-width:0}\n #prudleWorkspace .pw-form-shell{border:1px solid #dae5f2;border-radius:16px;background:#f8fbff;padding:18px;margin-bottom:16px}\n #prudleWorkspace .pw-form-shell>label{display:block;font-weight:900;color:#164478;margin:12px 0 5px}\n #prudleWorkspace .pw-form-shell>input,#prudleWorkspace .pw-form-shell>select{width:100%;margin:6px 0}\n #prudleWorkspace .pw-form-shell .row{display:flex;gap:9px}\n #prudleWorkspace .pw-rightnote{background:#eef6ff;padding:12px 15px;border:1px solid #cadef5;border-radius:12px;margin-bottom:15px;font-size:13px;color:#345775}\n #prudleWorkspace .pw-tools{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 16px}\n #prudleWorkspace .pw-tools button{width:auto!important;margin:0!important;padding:10px 13px!important;border-radius:10px!important;font-size:13px!important}\n #prudleWorkspace .pw-editor-page{background:#fff;min-height:65vh;padding:20px 26px;border:1px solid #dce6f3;border-radius:12px;box-shadow:0 9px 24px #16447811}\n #prudleWorkspace .pw-editor-page>.box{border:none!important;background:transparent!important;padding:0!important}\n #prudleWorkspace .pw-card-heading{color:#164478;margin:0 0 12px;font-size:22px;font-weight:900}\n #prudleWorkspace .pw-create-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}\n #prudleWorkspace .pw-create-grid>*{min-width:0}#prudleWorkspace .pw-create-grid>.pw-wide{grid-column:1/-1}\n #prudleWorkspace .pw-create-grid input,#prudleWorkspace .pw-create-grid select{width:100%;min-width:0}\n #prudleWorkspace .pw-create-grid button{max-width:100%}\n #prudleWorkspace .pw-panel #prudleAIQuiz{max-width:none!important;margin:0!important}\n #publishedQuestionsSidebar{z-index:2!important}\n #prudleWorkspace .pw-inline-editor{margin-top:20px;border-top:2px solid #d8e5f3;padding-top:18px}\n #prudleWorkspace .pw-inline-editor>summary{cursor:pointer;color:#174575;font-size:18px;font-weight:900;background:#edf4ff;padding:15px;border-radius:13px;margin-bottom:12px}\n #prudleWorkspace #pwPublishedInline{margin-top:14px;min-width:0}\n #prudleWorkspace #pwPublishedInline #publishedQuestionsSidebar{display:block!important;visibility:visible!important;opacity:1!important}\n @media(max-width:850px){#prudleWorkspace .pw-layout{grid-template-columns:1fr}#prudleWorkspace .pw-nav{position:static;max-height:none;display:flex;overflow:auto;gap:6px;align-items:center;flex-wrap:nowrap}#prudleWorkspace .pw-nav-title{display:none}#prudleWorkspace .pw-nav button{flex:0 0 auto;width:auto;min-width:110px;margin:0;padding:10px}#prudleWorkspace .pw-paper{padding:14px}#prudleWorkspace .pw-create-grid{grid-template-columns:1fr}#prudleWorkspace .pw-panel #optionsBox{grid-template-columns:1fr}}\n @media print{#prudleWorkspace .pw-nav,#prudleWorkspace .pw-heading,#prudleWorkspace .pw-tools{display:none!important}#prudleWorkspace .pw-layout{display:block}#prudleWorkspace .pw-paper{box-shadow:none;border:0}}\n `;document.head.appendChild(css);\n const root=document.createElement('section');root.id='prudleWorkspace';\n root.innerHTML=`<header class=\"pw-heading\"><div><strong>إدارة الاختبارات والكويزات</strong><small>واجهة تحرير منظمة على نمط ورقة الاختبار — Prudle Exams Studio</small></div><span>✍️ Exam Editor</span></header>\n <div class=\"pw-layout\"><nav class=\"pw-nav\" aria-label=\"أدوات إدارة الاختبارات\"><div class=\"pw-nav-title\">☰ لوحة الأدوات</div>\n <button type=\"button\" data-pw=\"view\" class=\"pw-active\">📄 ورقة الاختبار</button>\n <button type=\"button\" data-pw=\"edit\">✍️ إضافة / تعديل الأسئلة</button>\n <button type=\"button\" data-pw=\"create\">➕ إنشاء وربط اختبار</button>\n <button type=\"button\" data-pw=\"import\">📥 استيراد Word / PDF</button>\n <button type=\"button\" data-pw=\"tools\">⚙️ الإدارة والخيارات</button></nav>\n <main class=\"pw-main\"><section class=\"pw-panel pw-open\" id=\"pw-view\"><div class=\"pw-paper\"><header class=\"pw-paperhead\"><div><h2>ورقة الاختبار والأسئلة</h2><div class=\"pw-desc\">اختر الاختبار، ثم راجع الأسئلة والإجابات كما تظهر في الورقة. استخدم زر Edit داخل السؤال لتعديله.</div></div></header><div id=\"pwPreviewSlot\"></div><details id=\"pwInlineEdit\" class=\"pw-inline-editor\"><summary>✍️ إضافة سؤال أو تعديل السؤال المحدد</summary><div class=\"pw-editor-page\" id=\"pwEditorSlot\"></div></details></div></section>\n <section class=\"pw-panel\" id=\"pw-create\"><div class=\"pw-paper\"><h2 class=\"pw-card-heading\">إنشاء اختبار وربطه بالدورات</h2><p class=\"pw-desc\">اختر الفرع والقسم والدورات، ويمكنك اختيار اختبارات سابقة لنسخ أسئلتها.</p><div id=\"pwCreateSlot\" class=\"pw-create-grid\"></div></div></section>\n <section class=\"pw-panel\" id=\"pw-import\"><h2 class=\"pw-card-heading\">📥 استيراد الأسئلة ومراجعتها</h2><div id=\"pwImportSlot\"></div></section>\n <section class=\"pw-panel\" id=\"pw-ai\"><h2 class=\"pw-card-heading\">✨ إنشاء أسئلة بالذكاء الاصطناعي</h2><div id=\"pwAiSlot\"></div></section>\n <section class=\"pw-panel\" id=\"pw-tools\"><div class=\"pw-paper\"><h2 class=\"pw-card-heading\">أدوات إدارة الاختبار</h2><p class=\"pw-desc\">النسخ، ربط الأسئلة، إعادة المحاولة، خيارات العرض والطباعة؛ تستخدم الأدوات الأصلية دون إنشاء صلاحيات جديدة.</p><div id=\"pwActionsSlot\" class=\"pw-tools\"></div><div id=\"pwToolsInfo\" class=\"pw-rightnote\">اختر الاختبار من ورقة الاختبار أولًا عند استخدام الأدوات.</div></div></section>\n </main></div>`;\n const page=document.querySelector('.page');\n (page?.parentNode||document.body).insertBefore(root,page||null);\n function move(el,id){if(el&&$(id))$(id).appendChild(el)}\n move(preview,'pwPreviewSlot');move(editor,'pwEditorSlot');move(imports,'pwImportSlot');if(ai){move(ai,'pwAiSlot');const aiPanel=$('pw-ai');if(aiPanel){aiPanel.hidden=true;aiPanel.style.display='none';}}\n // Collect only original course-creation controls, without duplicating IDs or handlers.\n const branch=$('branchFilter'),title=$('examTitle');\n if(branch&&title&&branch.parentNode===title.parentNode){\n  const par=branch.parentNode, nodes=[...par.childNodes];let start=nodes.indexOf(branch),end=nodes.indexOf(title);\n  if(start>=0&&end>=start){\n   const createButton=nodes.slice(end).find(n=>n.nodeType===1&&n.tagName==='BUTTON'&&/createExam\\(/.test(n.getAttribute('onclick')||''));\n   if(createButton){let stop=nodes.indexOf(createButton);nodes.slice(start,stop+1).forEach(n=>{if(n.nodeType===1) n.classList.add('pw-wide');$('pwCreateSlot').appendChild(n)});page && (page.style.display='none');}\n  }\n }\n const pwActive=name=>{\n  document.querySelectorAll('#prudleWorkspace .pw-panel').forEach(p=>p.classList.toggle('pw-open',p.id==='pw-'+name));\n  document.querySelectorAll('#prudleWorkspace [data-pw]').forEach(b=>b.classList.toggle('pw-active',b.dataset.pw===name));\n  $('prudleWorkspace').scrollIntoView({behavior:'smooth',block:'start'});\n };\n root.querySelectorAll('[data-pw]').forEach(btn=>btn.addEventListener('click',()=>{if(btn.dataset.pw==='edit'){pwActive('view');const details=$('pwInlineEdit');if(details){details.open=true;details.scrollIntoView({behavior:'smooth',block:'start'});} }else{pwActive(btn.dataset.pw);} }));\n window.prudleOpenExamWorkspace=pwActive;\n // When a question's existing Edit action is invoked, show the page-like editor.\n if(typeof window.editQuestion==='function'){\n  const oldEdit=window.editQuestion;\n  window.editQuestion=function(...args){pwActive('view');const details=$('pwInlineEdit');if(details)details.open=true;return oldEdit.apply(this,args)};\n }\n // Move the original action buttons to management section, keeping their onclick handlers.\n const actionSlot=$('pwActionsSlot');\n const originalButtons=[...preview.querySelectorAll('button')];\n const actionNames=['toggleShuffle','toggleOnePageMode','deleteExam','editExamTime','loadQuestions'];\n originalButtons.filter(b=>actionNames.some(n=>(b.getAttribute('onclick')||'').includes(n+'('))).forEach(b=>actionSlot.appendChild(b));\n const quickActions=[\n  ['📄 معاينة الأسئلة',()=>window.prudleOpenPdfPreview?.('review')],\n  ['🖨️ PDF الأسئلة',()=>window.prudleOpenPdfPreview?.('questions')],\n  ['✅ PDF مع الإجابات',()=>window.prudleOpenPdfPreview?.('answers')],\n  ['📋 نسخ من اختبار سابق',()=>window.openQuestionCopyBank?.()],\n  ['⚙️ تنسيق ورقة الاختبار',()=>window.prudleV8OpenLayoutEditor?.()],\n  ['👁️ إدارة إظهار الأسئلة للطلاب',()=>{pwActive('tools');const pane=$('pwPublishedInline');if(pane)pane.scrollIntoView({behavior:'smooth',block:'nearest'});window.loadPublishedQuestionsSidebar?.(true)}]\n ];\n quickActions.forEach(([label,handler])=>{let b=document.createElement('button');b.type='button';b.textContent=label;b.addEventListener('click',handler);actionSlot.appendChild(b)});\n const published=$('publishedQuestionsSidebar');if(published){const mount=document.createElement('section');mount.id='pwPublishedInline';mount.className='pw-paper';const heading=document.createElement('h3');heading.textContent='إظهار وإخفاء أسئلة الطلاب حسب الدورة والنموذج';mount.appendChild(heading);actionSlot.after(mount);mount.appendChild(published);published.style.setProperty('position','relative','important');published.style.setProperty('inset','auto','important');published.style.setProperty('right','auto','important');published.style.setProperty('top','auto','important');published.style.setProperty('width','100%','important');published.style.setProperty('max-width','100%','important');published.style.setProperty('box-shadow','none','important');published.style.setProperty('transform','none','important');published.classList.remove('collapsed');}\n\n // Keep exam selection in the viewing area and the independent editor exam select in the edit area.\n // Avoid the old repair button if it appears in this build.\n [...document.querySelectorAll('button')].filter(b=>(b.textContent||'').includes('تصحيح ترتيب الإجابات القديمة')).forEach(b=>b.remove());\n // Preserve all dynamic questions and data fetching; only the containing UI has been changed.\n})();\n"});
   await installScript({text:"(function(){\n  'use strict';\n  // V15: isolated, lazy side filters. Does not override Prudle's original\n  // exam creation, editing, question save, or preview functions.\n  try {\n    const workspace=document.getElementById('prudleWorkspace');\n    const nav=workspace?.querySelector('.pw-nav');\n    if(!nav || document.getElementById('prudleV15Filters')) return;\n    const el=(tag,attrs={},txt='')=>{\n      const node=document.createElement(tag);\n      for(const [k,v] of Object.entries(attrs)) node.setAttribute(k,v);\n      if(txt)node.textContent=txt;\n      return node;\n    };\n    const wrap=el('section',{id:'prudleV15Filters',dir:'rtl'});\n    const style=el('style',{id:'prudleV15FilterStyles'});\n    style.textContent=`\n#prudleV15Filters{border-top:1px solid #dbe7f3;padding:14px 4px 6px;margin-top:9px;font-family:Tajawal,Arial,sans-serif;min-width:0}\n#prudleV15Filters .pv-title{font-weight:900;font-size:15px;color:#174575;margin:0 0 8px}\n#prudleV15Filters label{display:block;font-size:12px;font-weight:800;color:#284e76;margin:9px 0 4px}\n#prudleV15Filters input,#prudleV15Filters select{width:100%;min-width:0;box-sizing:border-box;border:1px solid #c9d9ef;background:#fff;color:#173f66;border-radius:10px;padding:10px 8px;font:700 13px Tajawal,Arial,sans-serif;margin:0}\n#prudleV15Filters input:focus,#prudleV15Filters select:focus{outline:2px solid #90b9e7}\n#prudleV15Filters .pv-status{font:700 11px Tajawal,Arial,sans-serif;color:#52687f;margin:9px 0;line-height:1.7}\n#prudleV15Filters .pv-results{display:grid;gap:6px;max-height:275px;overflow:auto}\n#prudleV15Filters button.pv-item{all:unset;box-sizing:border-box;display:block;cursor:pointer;width:100%;border:1px solid #dae5f3;border-radius:9px;background:#f4f8ff;color:#19466f;padding:9px;font:800 12px Tajawal,Arial,sans-serif;overflow-wrap:anywhere}\n#prudleV15Filters button.pv-item:hover{background:#e4f0fe}\n#prudleV15Filters .pv-muted{font-weight:500;color:#61778c;font-size:11px;display:block;margin-top:3px}\n@media(max-width:850px){#prudleV15Filters{flex:none;min-width:260px;max-width:310px;max-height:75vh;overflow:auto}}\n`;\n    document.head.appendChild(style);\n    wrap.appendChild(el('div',{class:'pv-title'},'🔎 تصفية الاختبارات'));\n    const makeInput=(title,id,tag,options)=>{\n      const l=el('label',{for:id},title);const ctrl=el(tag,{id});\n      if(options) for(const [value,label] of options) ctrl.appendChild(new Option(label,value));\n      wrap.append(l,ctrl);return ctrl;\n    };\n    const search=makeInput('البحث بالكلمات المفتاحية','prudleV15Search','input');\n    search.type='search';search.placeholder='اسم الاختبار أو المدرب...';\n    const skill=makeInput('المهارة','prudleV15Skill','select',[\n      ['','جميع المهارات'],['listening','Listening — الاستماع'],\n      ['speaking','Speaking — التحدث'],['grammar','Grammar — القواعد'],\n      ['vocabulary','Vocabulary — المفردات'],['reading','Reading — القراءة'],\n      ['writing','Writing — الكتابة']\n    ]);\n    const type=makeInput('نوع الاختبار','prudleV15ExamType','select',[\n      ['','جميع الأنواع'],['finalExam','Final Exam — نهائي'],\n      ['midterm','Midterm Exam — نصفي'],['quizEvaluation','Quiz / Evaluation — كويز'],\n      ['listening','Listening Exam'],['speaking','Speaking Exam']\n    ]);\n    const course=makeInput('الدورة المرتبطة بالأسئلة','prudleV15LinkedCourse','select',[\n      ['','جميع الدورات المرتبطة']\n    ]);\n    const status=el('div',{class:'pv-status',role:'status','aria-live':'polite'},'اضغط على حقل البحث أو الفلاتر لتحميل روابط الأسئلة.');\n    const results=el('div',{class:'pv-results'});\n    wrap.append(status,results);nav.appendChild(wrap);\n    let questions=null,loaded=false,loading=null,allExams=[];\n    const norm=x=>String(x??'').trim().toLowerCase();\n    const getExams=()=>{\n      try {\n        // Original application keeps this cache in its classic script global scope.\n        if(typeof EXAMS_DROPDOWN!=='undefined' && Array.isArray(EXAMS_DROPDOWN))\n          return EXAMS_DROPDOWN.slice();\n      }catch(_){}\n      return [];\n    };\n    function linkedIds(q){\n      const ids=[];\n      if(Array.isArray(q.coursesUsed)) for(const x of q.coursesUsed){\n        const id=String(x?.courseId||'').trim();if(id)ids.push(id);\n      }\n      return ids;\n    }\n    async function load(){\n      if(loaded)return;\n      if(loading)return loading;\n      status.textContent='جاري قراءة الدورات المرتبطة بالأسئلة...';\n      loading=(async()=>{\n        if(typeof db==='undefined'||!db?.collection)throw Error('اتصال قاعدة البيانات غير متاح');\n        const snapshot=await db.collection('questions').get();\n        const list=[];const courses=new Map();\n        snapshot.forEach(d=>{\n          const q=d.data()||{};\n          list.push({examId:String(q.examId||''),skill:norm(q.skill||''),group:norm(q.group||''),title:norm(q.question||''),courseIds:linkedIds(q)});\n          for(const c of Array.isArray(q.coursesUsed)?q.coursesUsed:[]){\n            const id=String(c?.courseId||'').trim();if(!id)continue;\n            const name=[c.TrainingCourse,c.Trainer,c.Period].filter(Boolean).map(String).join(' | ')||id;\n            if(!courses.has(id))courses.set(id,name);\n          }\n        });\n        questions=list;loaded=true;\n        const previous=course.value;\n        course.replaceChildren(new Option('جميع الدورات المرتبطة',''));\n        for(const [id,name] of [...courses.entries()].sort((a,b)=>a[1].localeCompare(b[1],'ar'))){\n          course.add(new Option(name,id));\n        }\n        if(courses.has(previous))course.value=previous;\n        status.textContent='تم تحميل '+list.length+' سؤال و'+courses.size+' دورة مرتبطة.';\n      })().catch(err=>{\n        console.warn('[Prudle V15 sidebar filters] Optional loading failed:',err);\n        status.textContent='تعذر تحميل الفلاتر. بقية لوحة الاختبارات تعمل كالمعتاد. '+String(err?.message||err);\n        questions=null;\n      }).finally(()=>{loading=null;});\n      return loading;\n    }\n    function render(){\n      allExams=getExams();\n      const query=norm(search.value),desiredSkill=norm(skill.value),desiredType=norm(type.value),wantedCourse=course.value;\n      // Do not mistake absent question linkage for a match.\n      const matching=allExams.filter(ex=>{\n        const title=norm(ex.title),cat=norm(ex.examCategory),meta=norm([ex.course,ex.trainer,ex.period].join(' '));\n        const related=(questions||[]).filter(q=>q.examId===String(ex.id));\n        if(query && !(title+' '+meta+' '+cat).includes(query) && !related.some(q=>q.title.includes(query)))return false;\n        if(desiredType && cat!==desiredType.toLowerCase() && !(desiredType==='finalExam'&&/final\\s*exam|نهائي/i.test(title)) && !(desiredType==='midterm'&&/midterm|نصفي/i.test(title)))return false;\n        if(desiredSkill && !(\n          related.some(q=>q.skill.includes(desiredSkill)||q.group.includes(desiredSkill)) ||\n          title.includes(desiredSkill) || (cat===desiredSkill)\n        ))return false;\n        if(wantedCourse && !related.some(q=>q.courseIds.includes(wantedCourse)))return false;\n        return true;\n      });\n      results.replaceChildren();\n      const max=100;\n      for(const exam of matching.slice(0,max)){\n        const btn=el('button',{type:'button',class:'pv-item'});\n        btn.textContent=exam.title||'Untitled';\n        const sub=el('span',{class:'pv-muted'},[exam.course,exam.trainer].filter(Boolean).join(' | '));btn.appendChild(sub);\n        btn.addEventListener('click',async()=>{\n          const examId=String(exam.id);\n          try {\n            // The original view panel must be visible before updating the preview.\n            document.querySelector('#prudleWorkspace [data-pw=\"view\"]')?.click();\n            // Make the selected exam visible in the original preview search/grid.\n            const previewSearch=document.getElementById('previewExamSearch');\n            if(previewSearch)previewSearch.value=String(exam.title||'');\n            if(typeof filterExamDropdown==='function')filterExamDropdown(String(exam.title||''));\n            else if(typeof window.filterExamDropdown==='function')window.filterExamDropdown(String(exam.title||''));\n            // Respect the linked course chosen in the sidebar, if the exam has\n            // questions linked to that course. Otherwise show the default tabs.\n            const linked=(questions||[]).some(q=>q.examId===examId&&q.courseIds.includes(course.value));\n            const focusCourse=course.value&&linked?course.value:'';\n            if(focusCourse){\n              const qLink=(questions||[]).find(q=>q.examId===examId&&q.courseIds.includes(focusCourse));\n              const label=Array.from(course.options).find(opt=>opt.value===focusCourse)?.textContent||'';\n              const parts=label.split(' | ');\n              if(typeof SIDEBAR_FOCUS_COURSE_ID!=='undefined')SIDEBAR_FOCUS_COURSE_ID=focusCourse;\n              if(typeof CURRENT_COURSE_ID!=='undefined')CURRENT_COURSE_ID=focusCourse;\n              if(typeof CURRENT_COURSE_NAME!=='undefined')CURRENT_COURSE_NAME=parts[0]||'';\n              if(typeof CURRENT_TRAINER!=='undefined')CURRENT_TRAINER=parts[1]||'';\n              if(typeof CURRENT_PERIOD!=='undefined')CURRENT_PERIOD=parts.slice(2).join(' | ');\n            }\n            // Open the original question loader. Do not replace its Firebase\n            // logic, save/edit actions, or course visibility rules.\n            if(typeof openExamTab==='function')await openExamTab(examId,!focusCourse);\n            else if(typeof window.openExamTab==='function')await window.openExamTab(examId,!focusCourse);\n            else if(typeof selectPreviewExam==='function')await selectPreviewExam(examId);\n            else if(typeof window.selectPreviewExam==='function')await window.selectPreviewExam(examId);\n            else throw Error('وظيفة اختيار الاختبار غير متاحة');\n            const select=document.getElementById('examSelect');\n            if(select && Array.from(select.options).some(opt=>opt.value===examId))select.value=examId;\n            const card=Array.from(document.querySelectorAll('#examPreviewBox .exam-card')).find(el=>el.dataset.id===examId);\n            if(card){\n              card.classList.add('exam-card-selected');\n              card.setAttribute('aria-current','true');\n              card.style.borderColor='#164478';\n              card.style.background='#eef5ff';\n              card.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'});\n            }\n            status.textContent='تم تحديد الاختبار وعرض أسئلته: '+String(exam.title||'');\n          }catch(err){\n            console.error('[Prudle V16] preview synchronization failed',err);\n            status.textContent='تعذر تحديث أسئلة الاختبار: '+String(err?.message||err);\n          }\n        });\n        results.appendChild(btn);\n      }\n      if(!matching.length)results.appendChild(el('div',{class:'pv-status'},'لا توجد اختبارات مطابقة.'));\n      if(matching.length>max)results.appendChild(el('div',{class:'pv-status'},'تم عرض أول '+max+' اختبار، استخدم البحث للتحديد.'));\n      status.textContent='عدد الاختبارات المطابقة: '+matching.length+(questions===null?' — روابط الأسئلة لم تُحمّل بعد.':'');\n    }\n    let debounce;\n    async function update(){\n      await load();\n      render();\n    }\n    for(const node of [search,skill,type,course]){\n      node.addEventListener(node===search?'input':'change',()=>{\n        clearTimeout(debounce);debounce=setTimeout(update,150);\n      });\n      node.addEventListener('focus',()=>{if(!loaded&&!loading)update();},{once:true});\n    }\n    // No network requests until someone actually uses this sidebar.\n  } catch(error){\n    console.error('[Prudle V15] Optional sidebar installation failed:',error);\n  }\n})();"});
 if(!cancelled&&PRUDLE_DESIGN_CONFIG.enabled)installProDesign();
 if(!cancelled)document.dispatchEvent(new Event('DOMContentLoaded',{bubbles:true}));
